create table if not exists public.post_bookmarks (post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create index if not exists post_bookmarks_user_created_idx on public.post_bookmarks(user_id,created_at desc);
alter table public.post_bookmarks enable row level security;
drop policy if exists "Citizens read their own bookmarks" on public.post_bookmarks;
create policy "Citizens read their own bookmarks" on public.post_bookmarks for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "Citizens save their own posts" on public.post_bookmarks;
create policy "Citizens save their own posts" on public.post_bookmarks for insert to authenticated with check(user_id=(select auth.uid()));
drop policy if exists "Citizens remove their own bookmarks" on public.post_bookmarks;
create policy "Citizens remove their own bookmarks" on public.post_bookmarks for delete to authenticated using(user_id=(select auth.uid()));
revoke all on public.post_bookmarks from anon,authenticated;
grant select,insert,delete on public.post_bookmarks to authenticated;
